CREATE TABLE applications (id varchar(64) PRIMARY KEY,code varchar(128) NOT NULL,name text NOT NULL,description text NOT NULL,icon text NOT NULL,home_path text NOT NULL,status varchar(32) NOT NULL,sort_order bigint NOT NULL DEFAULT 0,metadata json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY applications_code_unique(code),KEY applications_page_idx(status,sort_order,id));
CREATE TABLE navigations (id varchar(64) PRIMARY KEY,application_id varchar(64) NOT NULL,parent_id varchar(64) NULL,navigation_key varchar(128) NOT NULL,name text NOT NULL,navigation_type varchar(32) NOT NULL,route_path text NOT NULL,component text NOT NULL,icon text NOT NULL,resource varchar(128) NOT NULL,action varchar(128) NOT NULL,visible boolean NOT NULL DEFAULT true,status varchar(32) NOT NULL,sort_order bigint NOT NULL DEFAULT 0,metadata json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,CHECK((navigation_type='directory' AND component='' AND resource='' AND action='') OR (navigation_type='menu' AND route_path<>'' AND component<>'' AND resource<>'' AND action<>'')),UNIQUE KEY navigations_key_unique(application_id,navigation_key),KEY navigations_tree_idx(application_id,parent_id,sort_order,id),KEY navigations_target_idx(resource,action),CONSTRAINT navigations_application_fk FOREIGN KEY(application_id) REFERENCES applications(id),CONSTRAINT navigations_parent_fk FOREIGN KEY(parent_id) REFERENCES navigations(id));
CREATE TRIGGER applications_audit_bi BEFORE INSERT ON applications FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER applications_audit_bu BEFORE UPDATE ON applications FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER applications_audit_bd BEFORE DELETE ON applications FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER navigations_audit_bi BEFORE INSERT ON navigations FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER navigations_audit_bu BEFORE UPDATE ON navigations FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER navigations_audit_bd BEFORE DELETE ON navigations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
